-- Repair Agreement template, version 2: the Repair Limitations item said "except as stated in the Warranty below"
-- and Authorization listed "warranty", but the template had no warranty section. Version 2 adds a short
-- "Limited Workmanship Warranty" (the repaired areas, one year, fixed at no charge if the repair material itself
-- loses its bond, flakes or separates because of the workmanship; movement of the slab or soil and outside causes
-- excluded; written claim within 30 days; "does not limit any rights you have under North Carolina law") and points
-- both places at it.
-- The body is REPAIR_SEED from src/lib/crm/template-seeds.ts (the engine's tests run on it).
--
-- Data only. Skipped (with a notice) if the owner has already edited the Repair template, so their edits are
-- never replaced. Agreements already drafted keep their own copy of the template and do not change.

set local lock_timeout = '5s';

do $$
declare t uuid; v uuid; n int;
begin
  select id into t from public.document_templates where name = 'Repair Agreement' and status = 'active' limit 1;
  if t is null then
    raise notice 'no active Repair Agreement template; nothing to do';
    return;
  end if;
  select count(*) into n from public.document_template_versions where template_id = t;
  if n <> 1 then
    raise notice 'the Repair Agreement template has % versions (edited by the owner); left as is', n;
    return;
  end if;
  insert into public.document_template_versions (template_id, version_no, body, note, created_by_name)
    values (t, 2, $seed${"tax_mode":"includes_tax","clauses":[{"id":"clause.basics","kind":"clause","title":"Please Read — Concrete Basics","optional":false,"text":"- **Concrete cracks.** Hairline and shrinkage cracks, and cracking from ground movement, are normal and not a defect. Joints direct cracking but don't prevent it.\n- **Color, finish, and surface variation** (including efflorescence, the white haze) are normal.\n- **Stay off** new concrete for 24 hours; keep vehicles off for 7 days, heavy vehicles 28 days. Damage from early use is the customer's responsibility.\n- **We call 811** for public utilities. You must mark private lines (sprinklers, pet fence, lighting, private water/gas). Unmarked private lines aren't our responsibility.\n- **You confirm** that you own the property (or may authorize the work) and that it meets any HOA / setback rules.","text_includes_tax":null,"on_by_default":false},{"id":"clause.repair","kind":"initials","title":"Repair Limitations - Please Initial Each","optional":false,"text":"This is a repair to existing concrete, not a replacement. Please read and initial each item.\n\n- **Color and texture will not match.** Repair material comes from a different batch than the original concrete and will not match its color, shade, or texture exactly. Repaired areas will be visible and may weather differently over time. A color or texture difference is not a defect and is not a reason to withhold payment or to redo the work.\n- **Only the listed areas are repaired.** This job covers only the chips and cracks identified at the time of the estimate. The rest of the slab, adjacent concrete, and any areas not pointed out are not included or warranted.\n- **Existing conditions are not fixed.** The repair is cosmetic, not structural. It does not correct the causes of the damage, such as settlement, poor base, soil movement, tree roots, drainage, or freeze-thaw. Existing cracks may reopen or spread, and new cracks may form.\n- **No responsibility for future repairs.** Neither the Contractor nor Raleigh Concrete Group is responsible for any further repair, replacement, or resurfacing of this slab after this job, except as stated in the Limited Workmanship Warranty below.","text_includes_tax":null,"on_by_default":false},{"id":"clause.warranty","kind":"clause","title":"Limited Workmanship Warranty","text":"The Contractor warrants the workmanship on the repaired areas listed above for one (1) year from completion. If the repair material itself loses its bond, flakes, or separates from the existing concrete in that time because of how the work was done, the Contractor will fix it at no charge.\n\n- **Not covered:** color or texture differences; hairline cracks; cracks that reopen, or new cracks, caused by movement of the slab or the soil under it (such as settlement, tree roots, or drainage); anything outside the repaired areas; and damage from chemicals, impact, misuse, lack of maintenance, or freeze-thaw and de-icing salt that is not caused by the workmanship.\n- **How to claim:** tell the Contractor in writing within 30 days of noticing the problem. Fixing the faulty work is the remedy under this warranty.\n- Warranty claims are handled by the Contractor, not Raleigh Concrete Group. This warranty does not limit any rights you have under North Carolina law.","text_includes_tax":null,"optional":false,"on_by_default":false},{"id":"clause.responsible","kind":"clause","title":"Who's Responsible","optional":false,"text":"The Contractor is the party you're hiring and is responsible for the work, warranty, permits, and any claims. Raleigh Concrete Group is not the contractor, does not perform or warrant the work, and does not receive or hold your payment.","text_includes_tax":null,"on_by_default":false},{"id":"clause.insurance","kind":"clause","title":"Insurance","optional":false,"text":"The Contractor carries general liability insurance and will provide a certificate of insurance on request.\n\nRaleigh Concrete Group books the job only. It does not perform the work and does not carry insurance for it.","text_includes_tax":null,"on_by_default":false},{"id":"clause.liability","kind":"clause","title":"Limitation of Liability","optional":false,"text":"The Contractor's total liability for any claim related to this work is limited to the amount paid under this agreement. Neither the Contractor nor Raleigh Concrete Group is liable for indirect or consequential damages, such as loss of use or damage resulting from existing conditions. This does not limit liability for bodily injury or property damage caused by the Contractor's negligence, which is covered by the Contractor's insurance.","text_includes_tax":null,"on_by_default":false},{"id":"clause.cancel","kind":"clause","title":"Your Right to Cancel","optional":false,"text":"If you signed this at your home, you may cancel within 3 business days by written notice to Raleigh Concrete Group or the Contractor at the contact above. Any deposit is refunded within 10 days.","text_includes_tax":null,"on_by_default":false},{"id":"clause.authorization","kind":"clause","title":"Authorization","text":"I authorize the Contractor to perform the work described above at the price shown. I have read and understand the concrete basics, repair limitations, limited workmanship warranty, insurance, limitation of liability, and cancellation terms.","text_includes_tax":"I authorize the Contractor to perform the work described above for the total price shown, which includes all taxes and fees. I have read and understand the concrete basics, repair limitations, limited workmanship warranty, insurance, limitation of liability, and cancellation terms.","optional":false,"on_by_default":false}]}$seed$::jsonb, 'Limited Workmanship Warranty added; repair limitations and authorization now point to it', 'Wording fix (warranty)')
    returning id into v;
  update public.document_templates set current_version_id = v, updated_at = now() where id = t;
end $$;
